def transform(scores: dict, graph, question: str, question_date: str) -> dict:
    import math

    if not scores:
        return scores

    def get_session(turn_id):
        idx = turn_id.rfind('#')
        if idx >= 0:
            return turn_id[:idx]
        return turn_id

    # Group turns by session
    session_turns = {}
    for tid, sc in scores.items():
        sess = get_session(tid)
        if sess not in session_turns:
            session_turns[sess] = []
        session_turns[sess].append((tid, sc))

    # Sort each session's turns by score descending
    for sess in session_turns:
        session_turns[sess].sort(key=lambda x: -x[1])

    # For each session, compute rank within session
    turn_session_rank = {}
    for sess, turns in session_turns.items():
        for rank, (tid, sc) in enumerate(turns):
            turn_session_rank[tid] = rank

    # Sort all turns by score descending to get global rank
    sorted_turns = sorted(scores.items(), key=lambda x: -x[1])
    global_rank = {tid: i for i, (tid, sc) in enumerate(sorted_turns)}

    # Count how many turns per session appear in top-K globally
    total = len(scores)
    top_k = max(1, min(20, total // 2))

    session_top_count = {}
    for tid, rank in global_rank.items():
        if rank < top_k:
            sess = get_session(tid)
            session_top_count[sess] = session_top_count.get(sess, 0) + 1

    num_sessions = len(session_turns)

    new_scores = {}
    for tid, sc in scores.items():
        sess = get_session(tid)
        sess_rank = turn_session_rank[tid]
        g_rank = global_rank[tid]
        sess_count_in_top = session_top_count.get(sess, 0)
        sess_size = len(session_turns[sess])

        # Penalty for over-represented sessions: diminishing returns
        # If a session has many turns in top-k, penalize lower-ranked turns in that session
        if sess_count_in_top > 0:
            # Penalty increases with session rank (0 = best in session)
            # and with how over-represented the session is
            expected_per_session = top_k / max(num_sessions, 1)
            overrep = sess_count_in_top / max(expected_per_session, 1.0)
            # Apply penalty to turns beyond the first in a session
            if sess_rank > 0:
                penalty = math.log(1.0 + sess_rank) * math.log(1.0 + overrep) * 0.08
                sc = sc * (1.0 - min(penalty, 0.4))

        # Boost turns that are the best in their session but ranked low globally
        # This helps surface evidence from sessions not well represented
        if sess_rank == 0 and g_rank >= top_k:
            # Boost the best turn of an under-represented session
            boost = 0.05 * math.log(1.0 + g_rank - top_k + 1)
            sc = sc + boost

        new_scores[tid] = sc

    return new_scores

def transform(scores: dict, graph, question: str, question_date: str) -> dict:
    import math

    if not scores:
        return scores

    # Parse session id from turn_id (everything before the last '#')
    def get_session(turn_id):
        if '#' in turn_id:
            return turn_id.rsplit('#', 1)[0]
        return turn_id

    def get_turn_num(turn_id):
        if '#' in turn_id:
            try:
                return int(turn_id.rsplit('#', 1)[1])
            except Exception:
                return 0
        return 0

    # Sort turns by score descending
    sorted_turns = sorted(scores.items(), key=lambda x: x[1], reverse=True)

    # Count how many turns per session appear in top-N (simulate budget walk)
    # We'll apply a penalty based on how many same-session turns have higher scores
    session_rank_count = {}
    new_scores = {}

    for turn_id, score in sorted_turns:
        session = get_session(turn_id)
        if session not in session_rank_count:
            session_rank_count[session] = 0
        session_rank_count[session] += 1

    # Reset and apply diminishing returns
    session_seen = {}
    # Process in score order, track position within session
    turn_session_rank = {}
    for turn_id, score in sorted_turns:
        session = get_session(turn_id)
        if session not in session_seen:
            session_seen[session] = 0
        turn_session_rank[turn_id] = session_seen[session]
        session_seen[session] += 1

    # Compute global score stats
    all_scores = [s for _, s in scores.items()]
    max_score = max(all_scores)
    min_score = min(all_scores)
    score_range = max_score - min_score if max_score > min_score else 1.0

    # Count total turns per session
    session_total = {}
    for turn_id in scores:
        session = get_session(turn_id)
        session_total[session] = session_total.get(session, 0) + 1

    for turn_id, score in scores.items():
        session = get_session(turn_id)
        rank_in_session = turn_session_rank[turn_id]
        total_in_session = session_total[session]

        # Penalty for being a later-ranked turn within a session
        # First turn in session: no penalty
        # Each subsequent turn gets increasing penalty
        if rank_in_session == 0:
            penalty = 0.0
        else:
            # Stronger penalty for sessions with many turns
            # Use log to soften the penalty
            session_size_factor = math.log(1 + total_in_session) / math.log(2)
            penalty = rank_in_session * 0.04 * session_size_factor

        # Also boost turns that are the first in their session (likely summary/intro)
        turn_num = get_turn_num(turn_id)
        if turn_num == 0 and rank_in_session == 0:
            boost = 0.02
        else:
            boost = 0.0

        new_score = score - penalty + boost
        # Keep scores positive and preserve relative order within constraints
        new_scores[turn_id] = new_score

    return new_scores
